create table if not exists regulations (
  id bigint generated always as identity primary key,
  title text not null,
  body text,
  file_url text,
  file_name text,
  sort_order integer default 100,
  created_at timestamp with time zone default now()
);

alter table regulations enable row level security;
drop policy if exists "public read regulations" on regulations;
create policy "public read regulations" on regulations for select using (true);

insert into regulations (title, body, file_url, file_name, sort_order) values
('დებულება სპორტსმენთა და მწვრთნელთა ურთიერთობის შესახებ', '1. სპორტსმენის მიერ პირადი მწვრთნელის შეცვლა უნდა მოხდეს საქართველოს ძიუდოს ეროვნულ ფედერაციასთან შეთანხმებით, რა დროსაც ფედერაცია იმჟამინდელ და მომავალ მწვრთნელებთან ერთად განიხილავს ყველა დეტალს და მიიღებს გადაწყვეტილებას აღნიშნულ საკითხთან დაკავშირებით. ფედერაციის გარეშე ამ საკითხის გადაწყვეტა ჩაითვლება ბათილად და დავის წარმოშობის შემთხვევაში საკითხი გადაწყდება პირველი მწვრთნელის სასარგებლოდ. ამავე დროს სპორტსმენებს ეკრძალებათ პირად მწვრთნელად ჰყავდეთ ისეთი პიროვნება, რომელიც არ მოღვაწეობს ამ კუთხით, რაც უნდა გამოიხატებოდეს სისტემატური საწვრთნელი პროცესის წარმართვაში.

2. აეკრძალოს ეროვნული ნაკრები გუნდების მთავარ მწვრთნელებს პირადი მოსწავლის ყოლის უფლება. ზემოაღნიშნული შეეხოს აგრეთვე მთავარი მწვრთნელის თანაშემწეებს, იმ შემთხვევის გარდა, როდესაც მათ აქვთ დამოუკიდებლად გახსნილი სპორტული სექცია და ნაკრების სამწვრთნელო პროცესისგან თავისუფალ დროს ატარებენ ვარჯიშებს.', '/regulations/mcvrtneli-sportsmeni.pdf', 'დებულება სპორტსმენთა და მწვრთნელთა ურთიერთობის შესახებ', 1),
('დებულება ძიუდოისტთა სხვა ქვეყნის სახელით გამოსვლასთან დაკავშირებით (2013)', 'საქართველოს ძიუდოისტთა ეროვნული ნაკრები გუნდის წევრს, რომელიც მოისურვებს სხვა ქვეყნის სახელით გამოსვლას, მინიმუმ ორი წლის განმავლობაში ეთქვას უარი მოთხოვნის დაკმაყოფილებაზე. ნაკრები გუნდის წევრად განისაზღვროს სპორტსმენი, რომელსაც ერთხელ მაინც მიუღია მონაწილეობა საერთაშორისო ტურნირზე სახელმწიფოს დაფინანსებით.

აღნიშნული წესი ძალაში შევიდეს 2013 წლის 23 მაისიდან. რაც შეეხება სხვა დანარჩენ შემთხვევებს, რომელსაც ადგილი ჰქონდა ამ დრომდე, საქართველოს ძიუდოს ფედერაციის აღმასკომი იტოვებს უფლებას ინდივიდუალურად განიხილოს საკითხი თითოეულ სპორტსმენთან მიმართებაში.', '/regulations/debuleba-sazgvargaret-gadasvlaze.pdf', 'დებულება ძიუდოისტთა სხვა ქვეყნის სახელით გამოსვლასთან დაკავშირებით (2013)', 2),
('დებულება ჭაბუკთა და ახალგაზრდული ნაკრები გუნდის წევრთა წონის კლებასთან დაკავშირებით', '1. ჭაბუკთა (უმცროსი ასაკის ჭაბუკთა) და ახალგაზრდული ნაკრები გუნდის სპორტსმენთა ოფიციალურ შეჯიბრზე პირველ ნომრად წარდგენას იმ შემთხვევაში, როდესაც მისი წონა საშეჯიბრო წონასთან მიმართებაში არის ჭაბუკებში (უმცროს ასაკის ჭაბუკებში) 2 კგ-ით, ხოლო ახალგაზრდებში 3 კგ-ით მეტი, ნაკრები გუნდის მწვრთნელებთან ერთად წყვეტს აღმასკომის მიერ შექმნილი სპეციალური კომისია.

2. აღნიშნული დებულების შესრულების უზრუნველსაყოფად მოხდეს ჩემპიონებისა და პრიზიორების წონის კონტროლი ყოველი შიდა სარეიტინგო და საქართველოს პირველობების დამთავრებისთანავე.

3. ყოველივე ზემოაღნიშნულიდან გამომდინარე პირად მწვრთნელებს მიეცეთ მითითება არ დაუშვან შიდა სარეიტინგო და საქართველოს პირველობებზე ამ კატეგორიის სპორტსმენთა მონაწილეობა, წინააღმდეგ შემთხვევაში კომისიის მიერ მიღებული გადაწყვეტილება იქნება საბოლოო, რა დროსაც შესაძლებელია, მიუხედავად სპორტსმენის მიერ დაკავებული საპრიზო ადგილისა მას აეკრძალოს ასპარეზობა, როგორც ევროპისა და მსოფლიოს ჩემპიონატებზე, ასევე სხვადასხვა ოფიციალურ საერთაშორისო ტურნირზე.

4. საქართველოს ძიუდოს ფედერაციის მიერ დებულების მიღება განპირობებულია სპორტსმენთა ჯანმრთელობის დაცვისა და უფროს ასაკში მათ მიერ უკეთესი შედეგის მიღწევისათვის.', '/regulations/wonis-kleba.pdf', 'დებულება ჭაბუკთა და ახალგაზრდული ნაკრები გუნდის წევრთა წონის კლებასთან დაკავშირებით', 3),
('დებულება ძიუდოისტების სხვადასხვა სპორტის სახეობაში გამოსვლასთან დაკავშირებით', 'საქართველოს ძიუდოს სხვადასხვა ასაკობრივი ნაკრები გუნდის წევრის სურვილი ერთჯერადად სხვა სპორტის სახეობაში გამოსვლასთან დაკავშირებით უნდა შეთანხმდეს საქართველოს ძიუდოს ფედერაციასთან, წინააღმდეგ შემთხვევაში სადისციპლინო კომისიის გადაწყვეტილებით სპორტსმენს მიეცემა დისკვალიფიკაცია. საქართველოს ნაკრები გუნდის წევრად ჩაითვლება სპორტსმენი, რომელსაც ერთხელ მაინც მიუღია მონაწილეობა ფედერაციის მიერ დაფინანსებულ სასწავლო-საწვთრნელ შეკრებაში, ან საერთაშორისო ტურნირზე.', '/regulations/sxva-saxeobashi-gamosvla.pdf', 'დებულება ძიუდოისტების სხვადასხვა სპორტის სახეობაში გამოსვლასთან დაკავშირებით', 4),
('დებულება საქართველოს ეროვნულ ჩემპიონატში მონაწილეობის უფლების მქონე სპორტსმენების განსაზღვრის შესახებ', '1. საქართველოს პირველობაზე დაიშვებიან მხოლოდ ის სპორტსმენები, რომელნიც დაიკავებენ შესაბამის ადგილს აღმოსავლეთ და დასავლეთ საქართველოში ჩატარებულ სალიცენზიო, ზონალურ შეჯიბრში. კერძოდ: აღმოსავლეთ საქართველოში ჩასატარებელ ზონალური პირველობისთვის შესაბამის ადგილად განისაზღვროს 1/8 ფინალი, ხოლო დასავლეთ საქართველოში გასამართ შეჯიბრში მონაწილე სპორტსმენებითვის 1/4 ფინალი.

2. ყველა იმ სპორტსმენს, რომელიც ვერ დაიკავებს ზემოთ მითითებულ ადგილს, მიეცემა საქართველოს ეროვნულ ჩემპიონატზე გამოსვლის კიდევ ერთი შანსი: მოხდება წაგებული სპორტსმენების დაჯგუფება ხელახლა და მათ შორის ორი საუკეთესო მოიპოვებს ეროვნულ ჩემპიონატზე გამოსვლის უფლებას. ახალგაზრდებსა და ჭაბუკებში ორის ნაცვლად გათვალისწინებული იქნეს ოთხი ადგილი.

3. ზემოაღნიშნული წესი არ მოქმედებს იმ სპორტსმენების მიმართ, ვინც ერთხელ მაინც დაიკავა მინიმუმ მესამე საპრიზო ადგილი ევროპის, მსოფლიოს ან ოლიმპიურ თამაშებზე უფროსებში პირად პირველობაში. ამ კატეგორიის სპორტსმენებს ეძლევათ უფლება პირდაპირ მიიღონ მონაწილეობა ეროვნულ ჩემპიონატში.

4. საჭიროების შემთხვევაში ძიუდოს ეროვნული ფედერაცია უფლებას იტოვებს გამონაკლისი დაუშვას იმ სპორტსმენების მიმართ, რომელნიც მონაწილეობას მიიღებენ სხვადასხვა საერთაშორისო შეჯიბრში ზონალური ჩემპიონატის პარალელურად და პირდაპირ დაუშვას ეროვნულ ჩემპიონატზე.', '/regulations/agmaskomis_debuleba_sak_chemp_2015.pdf', 'დებულება საქართველოს ეროვნულ ჩემპიონატში მონაწილეობის უფლების მქონე სპორტსმენების განსაზღვრის შესახებ', 5),
('საკლუბო ჩემპიონატი — სტრუქტურა და განვითარების სტრატეგია', 'საკლუბო ჩემპიონატს დიდი მნიშვნელობა ენიჭება ძიუდოს პოპულარიზაციისა და შედეგიანობის ზრდის კუთხით — აპრობირებული სისტემაა მთელ რიგ მოწინავე ქვეყნებში (საფრანგეთი, გერმანია, იაპონია, ავსტრია). საქართველომ საკლუბო სისტემა 2013 წლიდან დანერგა, ხოლო 16 წლამდელთა საკლუბო ჩემპიონატის წარმატებამ საფუძველი დაუდო მისი გაფართოების იდეას უფროსების ასაკშიც.

გუნდები იქმნება 7 წონით კატეგორიაში (60, 66, 73, 81, 90, 100, +100 კგ) მხოლოდ იმ სპორტსმენებისგან, ვინც საპრიზო ადგილი დაიკავეს პირველი და მეორე დონის ეროვნულ ჩემპიონატებში, რეიტინგის მიხედვით თანაბარი სიძლიერის პრინციპით განაწილებული.

წარმომადგენელი (მწვრთნელ-მენეჯერი) შეირჩევა შემთხვევითი შერჩევის პრინციპით საუკეთესო კლუბების მწვრთნელთაგან და პასუხისმგებელია გუნდის საქმიანობაზე მთელი საშეჯიბრო წლის განმავლობაში.

შეჯიბრება ორ ეტაპად ტარდება — საკვალიფიკაციო (გაზაფხულზე, წრიული პრინციპით) და ფინალური (შემოდგომაზე, 4 საუკეთესო გუნდს შორის). დაფინანსებას სპორტისა და ახალგაზრდობის საქმეთა სამინისტრო უზრუნველყოფს — საკვალიფიკაციო ეტაპზე 147,000 ლარი, ფინალურ ეტაპზე კი 160,000 ლარი საპრიზო ფონდინაწილდება ადგილების მიხედვით.', '/regulations/club-cadet.pdf', 'საკლუბო ჩემპიონატი — სტრუქტურა და განვითარების სტრატეგია', 6),
('საკლუბო ჩემპიონატი ძიუდოში — შეჯიბრების ჩატარების სტრუქტურა', 'საკლუბო ჩემპიონატი ემსახურება ძიუდოს პოპულარიზაციასა და ფედერაციის გამართულ მუშაობას — სისტემა წარმომადგენლობით უფლებებს აძლევს მწვრთნელებს, რომლებიც რეალურად ქმნიან სპორტს, და თითოეულ კლუბს ეკრძალება სხვისი აღზრდილი სპორტსმენის გამოყვანა.

მონაწილეობის პრინციპები: კლუბმა განაცხადი უნდა გააკეთოს შეჯიბრებამდე ორი კვირით ადრე, თან დაერთოს რეესტრიდან ამონაწერი, საბანკო რეკვიზიტები, სპორტსმენთა/მწვრთნელთა სია და მონაწილეთა განაცხადი (მაქს. 10 სპორტსმენი). შეჯიბრება ტარდება გუნდურად, 5/5 პრინციპით — საკვალიფიკაციო ეტაპი გაზაფხულზე, ფინალური მოგვიანებით, „ოქროს ლიგასა" და „პირველ ლიგაში" დაყოფით.

საპრიზო ფონდის განკარგვა განისაზღვრება პროცენტულად: 25% მწვრთნელთა ხელფასები, 40% სპორტსმენთა სტიპენდია (განაწილებული მინიმუმ 6 თვეზე), 25% კლუბის განვითარება (ინვენტარი, კიმონოები, შეკრებები), 10% — კლუბის საკუთარი შეხედულებით, მწვრთნელთა პრემირების გარდა. ორგანიზებას ახორციელებს ფედერაცია, სპორტის სამინისტროს ხელშეწყობით.', '/regulations/club-project.pdf', 'საკლუბო ჩემპიონატი ძიუდოში — შეჯიბრების ჩატარების სტრუქტურა', 7),
('დებულება ზონალური წარმომადგენლობების შექმნისა და საქმიანობის შესახებ', 'რეგიონებთან ეფექტური კოორდინაციისთვის იქმნება აღმოსავლეთ და დასავლეთ საქართველოს ზონალური წარმომადგენლობები, თითოეულს ხელმძღვანელობს ზონალური წარმომადგენელი, რომელსაც ჰყავს აპარატი (მოადგილეები, საქმის მწარმოებელი, თანაშემწეები).

წარმომადგენლობები უზრუნველყოფენ ადგილობრივი და საერთაშორისო ტურნირების გამართვას, ახალგაზრდობის სპორტში ჩაბმას და ფედერაციასთან შეთანხმებული საქმიანობის განხორციელებას.

ზონალურ წარმომადგენელს 4 წლის ვადით ირჩევენ აღმასკომი და შესაბამის ზონაში მოღვაწე მწვრთნელები, ფარული კენჭისყრით (2+ კანდიდატის შემთხვევაში). არჩევნების პროცედურა (განაცხადები, დელეგატთა სია, კანდიდატურის წარდგენა) გაწერილია ვადებით — არჩევნებამდე 20 დღით ადრე ცხადდება თარიღი, 15 დღით ადრე დგინდება კანდიდატები. წარმომადგენელი ანგარიშვალდებულია აღმასკომის წინაშე.', '/regulations/zonaluri.pdf', 'დებულება ზონალური წარმომადგენლობების შექმნისა და საქმიანობის შესახებ', 8),
('დებულება ძიუდოისტთა სხვა ქვეყნის სახელით გამოსვლასთან დაკავშირებით (2019 რედაქცია)', 'საქართველოს ძიუდოისტთა ეროვნული ნაკრები გუნდის წევრს, რომელიც მოისურვებს სხვა ქვეყნის სახელით გამოსვლას, მინიმუმ სამი წლის განმავლობაში ეთქვას უარი მოთხოვნის დაკმაყოფილებაზე. ნაკრები გუნდის წევრად განისაზღვროს სპორტსმენი, რომელსაც ერთხელ მაინც მიუღია მონაწილეობა საერთაშორისო ტურნირზე საქართველოს ძიუდოს ფედერაციის დაფინანსებით.

აღნიშნულ წესში ფედერაციის აღმასრულებელი კომიტეტის მიერ შეტანილი ცვლილება ძალაში შევიდა 2019 წლის 21 იანვრიდან. დებულებაში შეტანილი ცვლილების თარიღამდე გათავისუფლება მიეცემათ მხოლოდ იმ სპორტსმენებს, რომლებსაც მინიმუმ ორი წელია არ უასპარეზიათ ეროვნული ნაკრები გუნდის სახელით. რაც შეეხება 30 წელს გადაცილებულ სპორტსმენებს, აღმასკომი იტოვებს უფლებას ინდივიდუალურად განიხილოს საკითხი თითოეულ სპორტსმენთან მიმართებაში.', '/regulations/sxva_saxelit.pdf', 'დებულება ძიუდოისტთა სხვა ქვეყნის სახელით გამოსვლასთან დაკავშირებით (2019 რედაქცია)', 9),
('აღმასკომის დადგენილება ფინანსური სახსრების ეფექტურ გამოყენებასთან დაკავშირებით ეროვნულ ნაკრებთან მიმართებაში', '1. ოლიმპიური ციკლის აქტიურ ფაზაში შესვლის გამო მოხდეს ფინანსური რესურსების მაქსიმალური მიმართვა ეროვნული ნაკრები გუნდისთვის, სხვა ასაკობრივ ნაკრებ გუნდებთან/პროგრამებთან შედარებით.

2-3. ჯანსაღი კონკურენციისთვის ნაკრები გუნდის მთავარ მწვრთნელს ეძლევა რეკომენდაცია 2019 წლის ევროპის ოლიმპიური თამაშებისთვის გუნდის შერჩევისას თანაბარი შესაძლებლობები მისცეს კონკურენციაში მყოფ სპორტსმენებს; დაკომპლექტებამდე შიდა შეკრებების ჩატარება არარეკომენდირებულია, დაზოგილი თანხა კი საკლუბო ჩემპიონატის საპრიზო ფონდისკენ მიემართება.

4. საკლუბო ჩემპიონატის საპრიზო ფონდი განისაზღვრა 1,000,000 ლარით — 70%-ით უფროს ასაკში გასამართ პირველობასთან მიმართებაში, რაც ხელს შეუწყობს საერთაშორისო შეჯიბრებზე ვერმოხვედრილ სპორტსმენებს.

5-6. ეს ასევე ხელს შეუწყობს პირადი მწვრთნელების ჩართულობას და კლუბებს/დარბაზებს შორის კონკურენციის ზრდას. გამონაკლისი დაწესდა 23 წლამდელთა ნაკრების უკვე დაგეგმილი იაპონიის შეკრებისთვის (10.02–28.02).', '/regulations/2019_01_22-dadgenileba_xarjebi.pdf', 'აღმასკომის დადგენილება ფინანსური სახსრების ეფექტურ გამოყენებასთან დაკავშირებით ეროვნულ ნაკრებთან მიმართებაში', 10);

select count(*) as regulations_count from regulations;